// 用法：node verify-detail-6073.mjs <detailHashPathWithId>
import { chromium } from '@playwright/test'
import path from 'path'
import fs from 'fs'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const SHOT = path.resolve(__dirname, '../../../.pua/shots')
const baseURL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8099'
const exe = process.env.PW_CHROME_PATH || path.join(process.env.LOCALAPPDATA || '', 'ms-playwright', 'chromium-1243', 'chrome-win64', 'chrome.exe')
const token = fs.readFileSync(path.join(SHOT, 'token.txt'), 'utf8').trim()
const hashPath = process.argv[2]

const browser = await chromium.launch({ headless: true, executablePath: exe })
const ctx = await browser.newContext({ baseURL, viewport: { width: 1680, height: 1200 } })
const page = await ctx.newPage()
page.setDefaultTimeout(30000)
await ctx.addInitScript((t) => { try { window.sessionStorage.setItem('Admin-Token', t) } catch (e) {} }, token)

const seen = []
page.on('response', (r) => {
  const u = r.url()
  if (/\/building\/(unit|house)\//.test(u)) seen.push(r.status() + ' ' + u.replace(baseURL, '').split('?')[0])
})

await page.goto('/#' + hashPath, { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(6000)
console.log('HASH', await page.evaluate(() => window.location.hash))
await page.screenshot({ path: path.join(SHOT, 'detail-page.png'), fullPage: true })

const toolbar = await page.locator('.operation-button-container button, .operation-button-container .el-button').allInnerTexts()
const norm = toolbar.map(s => s.replace(/\s+/g, '').trim()).filter(Boolean)
console.log('TOOLBAR', JSON.stringify(norm))
const bodyText = await page.evaluate(() => document.body.innerText)
console.log('BODY_HAS_单元拆分', bodyText.includes('单元拆分'))
console.log('HAS_房屋选择', bodyText.includes('房屋选择'))
console.log('API', JSON.stringify(seen.slice(-10)))
fs.writeFileSync(path.join(SHOT, 'detail-result.json'),
  JSON.stringify({ hash: await page.evaluate(() => window.location.hash), toolbar: norm, bodyHasUnitSplit: bodyText.includes('单元拆分'), hasHouseSelect: bodyText.includes('房屋选择'), api: seen }, null, 2))
await browser.close()
console.log('DONE')

