// 登录后台，打印 bizState 相关路由，并解析 unitinfo 详情的真实可用 hash 路径。
import { chromium } from '@playwright/test'
import path from 'path'
import fs from 'fs'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const SHOT = path.resolve(__dirname, '../../../.pua/shots')
const baseURL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8099'
const exe = process.env.PW_CHROME_PATH || path.join(process.env.LOCALAPPDATA || '', 'ms-playwright', 'chromium-1243', 'chrome-win64', 'chrome.exe')
const token = fs.readFileSync(path.join(SHOT, 'token.txt'), 'utf8').trim()

const browser = await chromium.launch({ headless: true, executablePath: exe })
const ctx = await browser.newContext({ baseURL, viewport: { width: 1680, height: 1200 } })
const page = await ctx.newPage()
page.setDefaultTimeout(30000)
await ctx.addInitScript((t) => { try { window.sessionStorage.setItem('Admin-Token', t) } catch (e) {} }, token)

const cap = []
page.on('response', async (r) => {
  const u = r.url()
  if (u.includes('/getRouters') || u.includes('/unit/') || u.includes('/menu/')) {
    if (u.includes('/getRouters')) {
      try { const j = await r.json(); cap.push(j) } catch (e) {}
    }
  }
})

await page.goto('/#/index', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(7000)
console.log('HASH_AFTER_INDEX', await page.evaluate(() => window.location.hash))

// 打印所有已注册路由（含 unitinfo）
const routes = await page.evaluate(() => {
  const app = document.querySelector('#app').__vue__
  const found = []
  const walk = (arr, parent) => (arr || []).forEach(r => {
    if (r.path && /unit|building/i.test(r.path + (r.name || '') + JSON.stringify(r.meta || {}))) {
      found.push({ path: r.path, name: r.name, meta: r.meta })
    }
    if (r.children) walk(r.children, r.path)
  })
  return found
}).catch(() => [])
console.log('ROUTES', JSON.stringify(routes, null, 2))

// 用 vue-router 解析
const resolved = await page.evaluate(() => {
  try {
    const app = document.querySelector('#app').__vue__
    const router = app.$router
    const out = []
    router.options.routes && router.options.routes.forEach(r => out.push(r.path))
    return { hasRouter: !!router, topPaths: out }
  } catch (e) { return { err: String(e) } }
})
console.log('RESOLVED', JSON.stringify(resolved))

await browser.close()
console.log('DONE')

