export function findRouterByFilePath(filePath, options = {}) {
  let routes = collectRoutesByFilePath(filePath)
  if (!routes.length && options.busCode) {
    routes = findMenuRoutesByBusCode(options.busCode)
  }
  const match = pickRouteByHints(routes, options)
  return match ? resolveRegisteredRoute(match) : null
