/** 按 filePath 构造 router.push 参数；含 :tableid 时用完整 path 替换为 id/add */
export function buildNavigationByFilePath(filePath, options = {}) {
  const {
    pathHint,
    menuId,
    busCode,
    preferDetail = false,
    routeId = 'add',
    query = {}
  } = options

  const matchRoute = findRouterByFilePath(filePath, {
    pathHint,
    menuId,
    busCode,
    preferDetail
  })
