// 登录后从 sessionStorage['routers'] 里找 unitinfo 详情路由，解析真实 hash，然后逐条访问并断言工具栏。
import { chromium } from '@playwright/test'
import path from 'path'
import fs from 'fs'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const SHOT = path.resolve(__dirname, '../../../.pua/shots')
const baseURL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8099'
const exe = process.env.PW_CHROME_PATH || path.join(process.env.LOCALAPPDATA || '', 'ms-playwright', 'chromium-1243', 'chrome-win64', 'chrome.exe')
const token = fs.readFileSync(path.join(SHOT, 'token.txt'), 'utf8').trim()

const browser = await chromium.launch({ headless: true, executablePath: exe })
const ctx = await browser.newContext({ baseURL, viewport: { width: 1680, height: 1200 } })
const page = await ctx.newPage()
page.setDefaultTimeout(30000)
await ctx.addInitScript((t) => { try { window.sessionStorage.setItem('Admin-Token', t) } catch (e) {} }, token)

await page.goto('/#/index', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(7000)

const candidates = await page.evaluate(() => {
  const raw = sessionStorage.getItem('routers')
  if (!raw) return { err: 'no routers key' }
  let data
  try { data = JSON.parse(raw) } catch (e) { return { err: 'json ' + e } }
  const out = []
  const walk = (arr, prefix) => (arr || []).forEach(r => {
    const full = r.path && r.path.startsWith('/') ? r.path : ((prefix || '') + '/' + (r.path || '')).replace(/\/+/g, '/')
    const hay = JSON.stringify({ p: r.path, c: r.component, m: r.meta }).toLowerCase()
    if (hay.includes('unitinfo') || hay.includes('building/unit')) {
      out.push({ path: full, rawPath: r.path, component: r.component, meta: r.meta })
    }
    if (r.children) walk(r.children, full)
  })
  walk(data, '')
  return { out }
})
console.log('CANDIDATES', JSON.stringify(candidates, null, 2).slice(0, 3000))
await browser.close()

